// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor1, address actor2, uint256 amount) public {
        vm.assume(actor1 != address(0) && actor2 != address(0));
        amount = bound(amount, 0, 10 ether);

        vm.deal(actor1, amount);
        vm.prank(actor1);
        c.Put{value: amount}(0);

        vm.deal(actor2, amount);
        vm.prank(actor2);
        bool ok;
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }

        assertTrue(ok, "a second Put by any actor must succeed after the lock is released");
    }
}
